package android.hardware;import java.util.*;public class SensorManager {public Map<Integer,Sensor> available=new HashMap<>();public boolean allow=true,denied;public int registered,unregistered,rate;public Sensor selected;public SensorEventListener listener;public Sensor getDefaultSensor(int type){return available.get(type);}public boolean registerListener(SensorEventListener listener,Sensor sensor,int interval){registered++;rate=interval;selected=sensor;if(denied)throw new SecurityException("blocked");this.listener=listener;return allow;}public void unregisterListener(SensorEventListener listener){unregistered++;this.listener=null;}public static void getRotationMatrixFromVector(float[] m,float[] q){float x=q[0],y=q[1],z=q[2],w=q.length>=4?q[3]:(float)Math.sqrt(Math.max(0,1-x*x-y*y-z*z));m[0]=1-2*y*y-2*z*z;m[1]=2*(x*y-z*w);m[2]=2*(x*z+y*w);m[3]=2*(x*y+z*w);m[4]=1-2*x*x-2*z*z;m[5]=2*(y*z-x*w);m[6]=2*(x*z-y*w);m[7]=2*(y*z+x*w);m[8]=1-2*x*x-2*y*y;}}
